public Detection detect(Bitmap bitmap) throws Throwable {
    Throwable th;
    requireBitmap(bitmap);
    Mats mats = new Mats();
    try {
        Mat rgba = boundedRgba(bitmap, MAX_DETECTION_EDGE, mats);
        Mat gray = mats.add(new Mat());
        Mat blur = mats.add(new Mat());
        Mat edges = mats.add(new Mat());
        Mat closedEdges = mats.add(new Mat());
        Imgproc.cvtColor(rgba, gray, 11);
        Imgproc.GaussianBlur(gray, blur, new Size(5.0d, 5.0d), AudioStats.AUDIO_AMPLITUDE_NONE);
        byte[] grayPixels = bytes(gray);
        int median = percentile(histogram(grayPixels), grayPixels.length, 0.5d);
        double lower = Math.max(25.0d, Math.min(80.0d, ((double) median) * 0.35d));
        double upper = Math.max(75.0d, Math.min(200.0d, 3.0d * lower));
        Imgproc.Canny(blur, edges, lower, upper);
        Mat edges2 = edges;
        byte[] edgePixels = bytes(edges2);
        Mat edgeKernel = mats.add(Imgproc.getStructuringElement(0, new Size(5.0d, 5.0d)));
        Imgproc.morphologyEx(edges2, closedEdges, 3, edgeKernel);
        int iCols = gray.cols();
        int median2 = gray.rows();
        Candidate best = findPage(closedEdges, edgePixels, grayPixels, iCols, median2, false, mats);
        Mat paperMask = mats.add(new Mat());
        double otsu = Imgproc.threshold(blur, paperMask, AudioStats.AUDIO_AMPLITUDE_NONE, 255.0d, 8);
        try {
            Imgproc.threshold(blur, paperMask, Math.max(125.0d, 0.92d * otsu), 255.0d, 0);
            mats = mats;
            Mat paperKernel = mats.add(Imgproc.getStructuringElement(0, new Size(9.0d, 9.0d)));
            Imgproc.morphologyEx(paperMask, paperMask, 3, paperKernel);
            int iCols2 = gray.cols();
            int iRows = gray.rows();
            Mat paperMask2 = paperMask;
            Candidate bright = findPage(paperMask2, edgePixels, grayPixels, iCols2, iRows, true, mats);
            Candidate best2 = (bright == null || (best != null && bright.score <= best.score)) ? best : bright;
            if (best2 != null && best2.score >= 0.6d) {
                PointF[] normalized = new PointF[4];
                int i = 0;
                for (int i2 = 4; i < i2; i2 = 4) {
                    normalized[i] = new PointF((float) (best2.points[i].x / ((double) (gray.cols() - 1))), (float) (best2.points[i].y / ((double) (gray.rows() - 1))));
                    i++;
                    paperMask2 = paperMask2;
                    rgba = rgba;
                    edges2 = edges2;
                }
                Detection detection = new Detection(normalized, best2.score);
                mats.close();
                return detection;
            }
            mats.close();
            return null;
        } catch (Throwable th2) {
            mats = mats;
            th = th2;
        }
    } catch (Throwable th3) {
        th = th3;
    }
    try {
        mats.close();
        throw th;
    } catch (Throwable th4) {
        th.addSuppressed(th4);
        throw th;
    }
}
